// generated by `pocket gen` from engine/*/meta/*.toml; do not edit

export interface Vec2 { x: number; y: number }
export interface Vec3 { x: number; y: number; z: number }
export interface Vec4 { x: number; y: number; z: number; w: number }
export interface Quat { x: number; y: number; z: number; w: number }
export interface Color { r: number; g: number; b: number; a: number }

/** Position, rotation and scale relative to the parent entity (or the world when there is no parent). */
export interface Transform {
    /** Local position in meters. */
    position: Vec3;
    /** Local rotation as a unit quaternion (x, y, z, w). */
    rotation: Quat;
    /** Local scale. */
    scale: Vec3;
}

/** World-space transform computed from the Transform hierarchy every tick. Read only. */
export interface WorldTransform {
    /** World position. */
    position: Vec3;
    /** World rotation. */
    rotation: Quat;
    /** World scale. */
    scale: Vec3;
}

/** Linear and angular velocity. The built-in motion system integrates Transform from it every tick. */
export interface Velocity {
    /** Meters per second, in the parent's space. */
    linear: Vec3;
    /** Radians per second around local X, Y, Z. */
    angular: Vec3;
}

/** Hit points. Gameplay decides what zero means; the engine only stores and reports it. */
export interface Health {
    /** Current hit points. */
    current: number;
    /** Maximum hit points. */
    max: number;
}

/** Seconds remaining before the entity is destroyed by the lifetime system. */
export interface Lifetime {
    /** Remaining seconds; the entity is destroyed when it reaches zero. */
    seconds: number;
}

/** The renderer uses the first active camera. Perspective by default; orthographic for 2D (looking down -Z with +Y up is the 2D convention). */
export interface Camera {
    /** Vertical field of view in degrees (perspective). */
    fov_degrees: number;
    /** Parallel projection: no perspective, sizes do not shrink with distance. */
    orthographic: boolean;
    /** Half of the visible height in world units when orthographic. */
    ortho_size: number;
    /** Near clip distance. */
    near: number;
    /** Far clip distance. */
    far: number;
    /** Whether this camera renders. */
    active: boolean;
}

/** A light source. kind 0 = directional (shines along -Z of the entity), 1 = point. */
export interface Light {
    /** 0 directional, 1 point. */
    kind: number;
    /** Linear RGB color; alpha unused. */
    color: Color;
    /** Multiplier applied to color. */
    intensity: number;
    /** Point light range in meters. */
    range: number;
}

/** Draws a mesh: a built-in primitive or a glTF file from the project's assets, tinted by a color and optionally textured. */
export interface MeshRenderer {
    /** cube, sphere, plane, cylinder, quad (unit square in XY facing +Z), or a project-relative glTF path such as assets/crate.glb (all of its nodes, with their own materials). */
    mesh: string;
    /** Base color, linear RGB; multiplies the asset's material color. */
    color: Color;
    /** Project-relative image (png, jpg) multiplied into the color; overrides the asset's base color texture. Empty for none. */
    texture: string;
    /** 0 dielectric to 1 metal; negative keeps the asset material's value (0 for primitives). */
    metallic: number;
    /** 0 mirror to 1 matte; negative keeps the asset material's value (1 for primitives). */
    roughness: number;
    /** Light the surface gives off regardless of lighting, added to the asset material's emissive color. */
    emissive: Color;
    /** Project-relative tangent-space normal map (+Y up); overrides the asset's. Empty for none. */
    normal_map: string;
    /** Whether the mesh is drawn. */
    visible: boolean;
}

/** A 2D image: a textured unit square in the entity's XY plane, sized in world units, unlit, alpha blended, drawn after meshes in layer order. Use with an orthographic camera looking down -Z. */
export interface Sprite {
    /** Project-relative image (png, jpg). Empty draws a solid color. */
    texture: string;
    /** Width and height in world units. */
    size: Vec2;
    /** Tint and opacity, multiplied into the texture. */
    color: Color;
    /** Point of the image at the entity's origin: (0,0) bottom-left, (0.5,0.5) center, (1,1) top-right. */
    anchor: Vec2;
    /** Draw order among sprites; higher is drawn later (on top). */
    layer: number;
    /** Sub-rectangle of the texture as u0, v0, u1, v1 (0..1, v down), for sprite sheets. */
    uv: Vec4;
    /** Mirror horizontally. */
    flip_x: boolean;
    /** Mirror vertically. */
    flip_y: boolean;
    /** Texture sampling: linear (smooth) or nearest (crisp pixels, no bleeding between sheet tiles). */
    filter: string;
    /** Whether the sprite is drawn. */
    visible: boolean;
}

/** Plays a clip (a run of sheet frames registered with sprite.clip or [sprite_clips] in project.toml) on the entity's Sprite: every tick the engine advances time, picks the frame and writes Sprite.uv (and texture when the clip names one). Emits sprite.finished when a non-looping clip ends. */
export interface SpriteAnimation {
    /** Clip name; empty plays nothing. */
    clip: string;
    /** Whether time advances. */
    playing: boolean;
    /** Wrap at the end (else stop on the last frame and emit sprite.finished); sprite.play takes it from the clip unless told otherwise. */
    loop: boolean;
    /** Playback rate multiplier; negative plays backwards. */
    speed: number;
    /** Frames per second; 0 uses the clip's rate. */
    fps: number;
    /** Index into the clip's frame list (read to know where it is, write to jump). */
    frame: number;
    /** Seconds into the current frame; advanced by the engine. */
    time: number;
    /** Set when a non-looping clip reached its end; cleared by play. */
    finished: boolean;
}

/** Draws a Tiled map (a .tmj file in the project) with the entity at the map's top-left corner: tile (x, y) occupies world x from x*tile_size to (x+1)*tile_size and y from -(y+1)*tile_size to -y*tile_size, so rows go down as in Tiled. Every visible tile layer is one static mesh drawn unlit through the sprite path (docs/design/tilemaps.md); tilemap.* commands answer what is where. */
export interface TileMap {
    /** Project-relative Tiled JSON map (.tmj). */
    map: string;
    /** Draw only this tile layer; empty draws every visible one. */
    layer: string;
    /** World units per tile. */
    tile_size: number;
    /** Tint and opacity over the whole map. */
    color: Color;
    /** Draw order among sprites (Sprite.layer); layers of the map draw in file order on top of this. */
    order: number;
    /** Whether the map is drawn. */
    visible: boolean;
}

/** Plays a glTF animation clip of the entity's MeshRenderer asset: every tick the engine advances time, samples the clip's keyframes into the file's node hierarchy and poses the skinned mesh (docs/design/animation.md). Emits animation.finished when a non-looping clip ends. Use animation.play / animation.stop, or set the fields directly. */
export interface Animator {
    /** Clip name from the asset (animation.clips lists them); empty plays nothing (bind pose). */
    clip: string;
    /** Whether time advances. */
    playing: boolean;
    /** Wrap at the end (else stop on the last frame and emit animation.finished). */
    loop: boolean;
    /** Playback rate multiplier. */
    speed: number;
    /** Seconds into the clip; advanced by the engine, writable to seek. */
    time: number;
    /** Set when a non-looping clip reached its end; cleared by play. */
    finished: boolean;
    /** Seconds of cross-fade from from_clip into clip; animation.play {fade} sets it. 0 when no fade is running. */
    fade: number;
    /** Seconds into the cross-fade, advanced by the engine; the blend weight is fade_time / fade, smoothed. */
    fade_time: number;
    /** The clip fading out (keeps playing at its own time until the fade ends); empty when none. */
    from_clip: string;
    /** Seconds into from_clip, advanced by the engine. */
    from_time: number;
}

/** Spawns particles at the entity: small unlit quads (camera-facing billboards, or XY sprites) with a life, a velocity from a cone, gravity, drag, and size and color fading from start to end. Simulated by the engine on the fixed tick with a random stream seeded from the entity, so runs are deterministic. particles.burst emits a batch at once. */
export interface ParticleEmitter {
    /** Project-relative image; empty draws soft solid quads. */
    texture: string;
    /** Whether particles spawn continuously at rate. */
    emitting: boolean;
    /** Particles per second while emitting. */
    rate: number;
    /** Most particles alive at once from this emitter (older ones are not replaced; spawning waits). */
    max: number;
    /** Seconds a particle lives: min and max, drawn uniformly. */
    lifetime: Vec2;
    /** Initial speed: min and max. */
    speed: Vec2;
    /** Center of the emission cone, in the emitter's local frame. */
    direction: Vec3;
    /** Half-angle of the cone in degrees (0 is a beam, 180 is every direction). */
    spread: number;
    /** Acceleration applied to every particle, world units per second squared. */
    gravity: Vec3;
    /** Fraction of velocity lost per second. */
    drag: number;
    /** Quad size in world units at birth and at death. */
    size: Vec2;
    /** Tint at birth. */
    color: Color;
    /** Tint at death; alpha 0 fades out. */
    color_end: Color;
    /** Draw order among sprites and particles. */
    layer: number;
    /** Face the camera (3D); false keeps quads in the XY plane for 2D scenes. */
    billboard: boolean;
    /** Particles keep their world position when the emitter moves; false moves them with it. */
    world_space: boolean;
    /** Extra seed for the emitter's random stream (the entity id seeds it too). */
    seed: number;
}

/** Axis-aligned bounding box in world space, computed by the engine from the mesh and WorldTransform. Read only. */
export interface Bounds {
    /** Minimum corner. */
    min: Vec3;
    /** Maximum corner. */
    max: Vec3;
}

/** Physics body. Dynamic bodies fall and collide; static bodies never move; kinematic bodies move by their Velocity and push dynamic ones. Uses the entity's Transform as world space (physics entities should be roots). */
export interface RigidBody {
    /** 0 dynamic, 1 static, 2 kinematic. */
    kind: number;
    /** Kilograms; ignored for static bodies. */
    mass: number;
    /** Bounciness 0..1. */
    restitution: number;
    /** Coulomb friction coefficient. */
    friction: number;
    /** Velocity lost per second (fraction). */
    linear_damping: number;
    /** Angular velocity lost per second (fraction). */
    angular_damping: number;
    /** Multiplier on world gravity. */
    gravity_scale: number;
    /** Set by the engine when the body came to rest; cleared when touched. */
    sleeping: boolean;
    /** Never rotate (characters on capsules stay upright). */
    lock_rotation: boolean;
}

/** Connects this body to another body, to any entity as a fixed point, or to a point in the world: a distance joint keeps two anchors a rod's length apart (or a rope's, pulling only), a ball joint pins them together while both rotate freely. Solved with the contacts every tick; when the force carried exceeds break_force the joint breaks (joint.broken event, component removed). */
export interface Joint {
    /** 0 distance (rod, or rope when rope is set), 1 ball (anchors pinned together). */
    kind: number;
    /** Path or name of the other entity (a body, or any entity as an immovable point); empty pins to the world point target_anchor. */
    target: string;
    /** Attachment point on this body, in its local frame. */
    anchor: Vec3;
    /** Attachment point on the target in its local frame, or a world point when there is no target. */
    target_anchor: Vec3;
    /** Rest length of a distance joint; negative takes the anchors' distance at the first step and writes it here. */
    distance: number;
    /** Distance joints only: pull when the anchors are farther than distance, never push. */
    rope: boolean;
    /** Force (newtons) above which the joint breaks; 0 never breaks. */
    break_force: number;
    /** Force the joint carried in the last step, written by the engine. */
    force: number;
}

/** Collision shape centered on the entity (plus offset). Box half extents come from size; spheres use size.x as radius. Triggers report overlaps but do not push. */
export interface Collider {
    /** 0 box, 1 sphere, 2 capsule (a segment along local Y with round ends). */
    shape: number;
    /** Box half extents; radius in x for spheres; radius in x and half length of the straight part in y for capsules. */
    size: Vec3;
    /** Local offset of the shape center. */
    offset: Vec3;
    /** Overlap events only, no collision response. */
    is_trigger: boolean;
}

/** A sound attached to an entity: the engine starts it when autoplay is set (once, when the component appears or the scene loads) and keeps `playing` and `voice` current. Scripts use audio.play for one-shots. */
export interface AudioSource {
    /** Project-relative WAV path such as assets/hum.wav. */
    clip: string;
    /** Linear gain, 0..4. */
    volume: number;
    /** Playback rate multiplier. */
    pitch: number;
    /** Restart when the clip ends. */
    loop: boolean;
    /** Start playing as soon as the component exists. */
    autoplay: boolean;
    /** Whether a voice is currently playing this source (written by the engine). */
    playing: boolean;
    /** Id of the playing voice, 0 when silent (written by the engine). */
    voice: number;
}

export interface Components {
    Transform: Transform;
    WorldTransform: WorldTransform;
    Velocity: Velocity;
    Health: Health;
    Lifetime: Lifetime;
    Camera: Camera;
    Light: Light;
    MeshRenderer: MeshRenderer;
    Sprite: Sprite;
    SpriteAnimation: SpriteAnimation;
    TileMap: TileMap;
    Animator: Animator;
    ParticleEmitter: ParticleEmitter;
    Bounds: Bounds;
    RigidBody: RigidBody;
    Joint: Joint;
    Collider: Collider;
    AudioSource: AudioSource;
}

export type ComponentName = keyof Components;

export const componentNames: readonly ComponentName[] = ["Transform", "WorldTransform", "Velocity", "Health", "Lifetime", "Camera", "Light", "MeshRenderer", "Sprite", "SpriteAnimation", "TileMap", "Animator", "ParticleEmitter", "Bounds", "RigidBody", "Joint", "Collider", "AudioSource"];

